import React, { useState, useEffect } from 'react';
import { db } from '../firebase';

function ContactForm({ selectedService, onClearService, showAlert }) {
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    email: '',
    service: '',
    message: ''
  });
  const [loading, setLoading] = useState(false);

  // Sync selectedService prop from Showcase cards selection
  useEffect(() => {
    if (selectedService) {
      let defaultMsg = '';
      if (selectedService === 'Calendar Printing') {
        defaultMsg = "Hi, I would like to order a Custom Tamil Calendar (Wall / Desk size). Please share pricing details.";
      }
      setFormData(prev => ({ 
        ...prev, 
        service: selectedService,
        message: defaultMsg || prev.message
      }));
    }
  }, [selectedService]);

  const handleChange = (e) => {
    const { id, value } = e.target;
    let val = value;

    // Custom restrictions matching index.html
    if (id === 'msg-name') {
      val = value.replace(/[^A-Za-z\s]/g, '');
    } else if (id === 'msg-phone') {
      val = value.replace(/[^0-9]/g, '').slice(0, 10);
    } else if (id === 'msg-email') {
      val = value.toLowerCase();
    }

    const fieldMap = {
      'msg-name': 'name',
      'msg-phone': 'phone',
      'msg-email': 'email',
      'msg-service': 'service',
      'msg-content': 'message'
    };

    setFormData(prev => ({ ...prev, [fieldMap[id]]: val }));
  };

  const handleInboundMessage = async (event) => {
    event.preventDefault();
    const { name, phone, email, service, message } = formData;

    // --- Validation ---
    if (!/^[A-Za-z\s]{3,20}$/.test(name)) {
      showAlert('Name must be 3–20 characters and contain letters only.', 'error');
      return;
    }
    if (!/^[0-9]{10}$/.test(phone)) {
      showAlert('Mobile number must be exactly 10 digits (no prefix).', 'error');
      return;
    }
    if (!/^[a-zA-Z0-9._%+\-]+@gmail\.com$/.test(email)) {
      showAlert('Please enter a valid Gmail address ending with @gmail.com.', 'error');
      return;
    }
    if (!service) {
      showAlert('Please select a service.', 'warning');
      return;
    }
    if (message.length < 5) {
      showAlert('Please enter a message (at least 5 characters).', 'warning');
      return;
    }

    setLoading(true);

    try {
      const timestamp = new Date().toISOString().replace('T', ' ').substring(0, 19);

      // 1. Submit to Firestore if database is initialized
      if (db) {
        await db.collection("customer_inquiries").add({
          name,
          phone: "+91 " + phone,
          email,
          service,
          message,
          timestamp,
          status: 'Pending'
        });
      }

      // 2. Submit to local Python server in background (optional)
      try {
        await fetch('http://localhost:8000/api/contact', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
